package com.nexushr.controller; import com.nexushr.dto.RequestDtos.PerformanceRequest; import com.nexushr.entity.PerformanceReview; import com.nexushr.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*; @RestController @RequestMapping("/performance") public class PerformanceController {final PerformanceService s;public PerformanceController(PerformanceService s){this.s=s;} @GetMapping("/me") public List<PerformanceReview> mine(Principal p){return s.mine(p.getName());} @PostMapping("/employee/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public PerformanceReview create(@PathVariable UUID id,@RequestBody PerformanceRequest x){return s.create(id,x);}}
